const quotationNo = 'QUO-' + new Date().getFullYear() + '-' + Math.floor(1000 + Math.random() * 9000);
const clientName = '卓越數位行銷有限公司';
const clientTaxId = '12345678';

// 動態商品清單
const items = [
  { name: 'n8n 企業版私有化部署服務', qty: 1, price: 45000 },
  { name: 'LINE / Telegram 雙向通訊機器人客製模組', qty: 2, price: 18000 },
  { name: 'AI 向量知識庫 (RAG) 企業規章串接', qty: 1, price: 25000 },
  { name: '年度 7x24 小時專屬技術維護保固', qty: 1, price: 12000 }
];

// 計算小計與總額
let subtotal = 0;
const formattedItems = items.map(item => {
  const itemTotal = item.qty * item.price;
  subtotal += itemTotal;
  return {
    name: item.name,
    qty: item.qty,
    price: '$' + item.price.toLocaleString(),
    subtotal: '$' + itemTotal.toLocaleString()
  };
});

const tax = Math.round(subtotal * 0.05);
const grandTotal = subtotal + tax;

return [{
  json: {
    quotationNo,
    clientName,
    clientTaxId,
    date: new Date().toISOString().split('T')[0],
    items: formattedItems,
    subtotal: '$' + subtotal.toLocaleString(),
    tax: '$' + tax.toLocaleString(),
    grandTotal: '$' + grandTotal.toLocaleString()
  }
}];
